SELECT variable_name, variable_value FROM performance_schema.global_status WHERE variable_name IN ('Innodb_buffer_pool_reads','Innodb_buffer_pool_read_requests','Innodb_data_reads','Innodb_rows_read','Sort_merge_passes','Created_tmp_disk_tables','Innodb_buffer_pool_pages_free');
SELECT SQL_NO_CACHE COUNT(*), MAX(product_name) FROM (SELECT product_id, product_name FROM search_document WHERE active=TRUE AND MATCH(search_text) AGAINST ('반려 건강' IN BOOLEAN MODE) ORDER BY MATCH(search_text) AGAINST ('반려 건강' IN BOOLEAN MODE) DESC, product_id LIMIT 21) t;
